#include <SPI.h>
#include <Ethernet.h>
#include <Wire.h>
#include <Adafruit_BMP085.h>

byte mac[] = { 0xDE, 0xAD, 0xBE, 0xEF, 0xFE, 0xED };
EthernetServer server(80);
Adafruit_BMP085 bmp;

void setup() {
  Serial.begin(9600);
  if (Ethernet.begin(mac) == 0) {
    Serial.println("DHCP Failed!");
  }
  server.begin();
  bmp.begin();
  Serial.print("Server online at: ");
  Serial.println(Ethernet.localIP());
}

void loop() {
  EthernetClient client = server.available();
  if (client) {
    boolean currentLineIsBlank = true;
    while (client.connected()) {
      if (client.available()) {
        char c = client.read();
        if (c == '\n' && currentLineIsBlank) {
          client.println("HTTP/1.1 200 OK");
          client.println("Content-Type: text/html");
          client.println("Connection: close");
          client.println("Refresh: 5"); // Auto-refresh
          client.println();
          client.println("<!DOCTYPE HTML>");
          client.println("<html><h1>Monster Lab Weather Beacon</h1>");
          client.print("<p>Temperature: "); client.print(bmp.readTemperature()); client.println(" C</p>");
          client.print("<p>Pressure: "); client.print(bmp.readPressure() / 100.0); client.println(" hPa</p>");
          client.print("<p>Altitude: "); client.print(bmp.readAltitude()); client.println(" m</p></html>");
          break;
        }
        if (c == '\n') currentLineIsBlank = true;
        else if (c != '\r') currentLineIsBlank = false;
      }
    }
    delay(1);
    client.stop();
  }
}
